#!/usr/bin/env node
// Generated by OrchestKit Claude Plugin
// Created: 2026-10-30
// ============================================================================
// design-ship names its bundle source for a URL and for a local file
// ============================================================================
// WHAT THIS GUARDS
//
//   design-ship accepts a handoff URL or a local bundle file, and the
//   Standalone Claude Design notice (#4882) tells users to prefer the file.
//   The Phase 4 PR body linked `{bundle_url}`, which only the URL input
//   defines, so the documented file flow opened a PR with an unresolved
//   placeholder (#4938, found by CodeRabbit on #4882).
//
//   Fails if: the Phase 4 pr_body uses `{bundle_url}`, does not use
//   `{bundle_source}`, or Phase 1 does not define bundle_source for both the
//   URL input and the local file input.
// ============================================================================

import { readFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.join(path.dirname(fileURLToPath(import.meta.url)), '..', '..', '..');
const FILE = path.join(ROOT, 'src', 'skills', 'design-ship', 'SKILL.md');
const text = readFileSync(FILE, 'utf8');

const section = (title) => {
  const start = text.search(new RegExp(`^## ${title}`, 'm'));
  if (start < 0) return '';
  const rest = text.slice(start + 3);
  const end = rest.search(/^## /m);
  return end < 0 ? rest : rest.slice(0, end);
};

const phase1 = section('Phase 1');
const phase4 = section('Phase 4');
const prBody = (/pr_body = f"""([\s\S]*?)"""/.exec(phase4) || [])[1];

const failures = [];
if (!phase1) failures.push('no "## Phase 1" section in design-ship SKILL.md');
if (prBody === undefined) failures.push('no pr_body f-string in the Phase 4 section');
if (prBody !== undefined) {
  if (prBody.includes('{bundle_url}')) {
    failures.push('Phase 4 pr_body uses {bundle_url}, which a local bundle file never defines (#4938)');
  }
  if (!prBody.includes('{bundle_source}')) {
    failures.push('Phase 4 pr_body does not link {bundle_source}');
  }
}
if (phase1) {
  if (!/bundle_source/.test(phase1)) {
    failures.push('Phase 1 does not define bundle_source');
  } else {
    if (!/bundle_source[^\n]*\burl\b/i.test(phase1)) failures.push('Phase 1 does not set bundle_source for a URL input');
    if (!/bundle_source[^\n]*\bfile\b/i.test(phase1)) failures.push('Phase 1 does not set bundle_source for a local file input');
  }
}

for (const f of failures) console.log(`FAIL: ${f}`);
if (failures.length) process.exit(1);
console.log('PASS: design-ship links one bundle_source that both inputs define');
